SELECT x.id,x.project_id AS "projectId",x.version,x.status,x.document,x.plan_id AS "planId", x.created_at AS "createdAt",COALESCE((SELECT json_agg(t ORDER BY position) FROM (SELECT position,local_number AS "localNumber",canonical_number AS "number",status,reason FROM planned_issues WHERE publication_id=x.id)t),'[]') AS issues FROM publications x WHERE x.workspace_id=$1 ORDER BY x.created_at DESC,x.id LIMIT 100
